```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class CustomerDatabase {

    private static final String URL = "jdbc:mysql://localhost:3306/your_database"; // Update with your database URL
    private static final String USER = "your_username"; // Update with your database username
    private static final String PASSWORD = "your_password"; // Update with your database password

    public static void getCustomerById(int customerId) {
        String query = "SELECT * FROM customers WHERE customer_id = ?";

        try (Connection connection = DriverManager.getConnection(URL, USER, PASSWORD);
             PreparedStatement preparedStatement = connection.prepareStatement(query)) {

            preparedStatement.setInt(1, customerId);
            ResultSet resultSet = preparedStatement.executeQuery();

            if (resultSet.next()) {
                // Assuming the customers table has columns: id, name, email
                int id = resultSet.getInt("customer_id");
                String name = resultSet.getString("name");
                String email = resultSet.getString("email");

                System.out.println("Customer ID: " + id);
                System.out.println("Name: " + name);
                System.out.println("Email: " + email);
            } else {
                System.out.println("No customer found with ID: " + customerId);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        int customerId = 1; // Example customer ID
        getCustomerById(customerId);
    }
}
```

### Explanation:
- **Connection**: Establishes a connection to the SQL database using JDBC.
- **PreparedStatement**: Prevents SQL injection by allowing you to set parameters.
- **ResultSet**: Retrieves the data returned by the SQL query.
- **Error Handling**: Catches and prints SQL exceptions.

Make sure to update the database URL, username, and password with your actual database credentials. You also need to include the MySQL JDBC driver in your project's dependencies to run this code successfully.

